var CHART_IMAGE = { src: "/og/cardology-birthday-chart.png", width: 1600, height: 2100, alt: "Cardology birthday chart: playing card for every birthday" };
function renderBirthdayChart() {
  let head = `<th scope="col" class="daycol">Day</th>`;
  for (let m = 1; m <= 12; m++) head += `<th scope="col"><abbr title="${MONTH_CAP[m - 1]}">${MONTH_CAP[m - 1].slice(0, 3)}</abbr></th>`;
  let rows = "";
  for (let d = 1; d <= 31; d++) {
    let cells = "";
    for (let m = 1; m <= 12; m++) {
      if (d > DAYS_IN_MONTH[m - 1]) {
        cells += `<td class="none" aria-label="${MONTH_CAP[m - 1]} ${d} does not exist">\xB7</td>`;
        continue;
      }
      const c = birthCardFor(m, d);
      const isJoker = c === "Joker";
      const cls = isJoker ? "jk" : SUIT_RED[suitOf(c)] ? "rs" : "bs";
      const face = isJoker ? "Joker" : `${rankOf(c)}${suitOf(c)}`;
      cells += `<td><a class="${cls}" href="/born-on/${daySlug(m, d)}" title="${dayLabel(m, d)}: ${isJoker ? "the Joker" : cardName(c)}">${face}</a></td>`;
    }
    rows += `<tr><th scope="row">${d}</th>${cells}</tr>`;
  }
  return `<div class="chartwrap" tabindex="0" role="region" aria-label="Cardology birthday chart, months across and days down">
<table class="chart"><caption>Cardology birthday chart. Rows are days of the month, columns are months. Each cell is the playing card for that birthday and links to its page.</caption>
<thead><tr>${head}</tr></thead><tbody>${rows}</tbody></table></div>
<p class="muted" style="font-size:.86rem">Red is Hearts and Diamonds, black is Clubs and Spades. Every cell links to that birthday\u2019s page. December 31 is the Joker: the one date the 52-card map leaves unassigned. It prefers it that way.</p>
<figure class="chartfig">
<a href="${CHART_IMAGE.src}" title="Open the printable Cardology birthday chart (PNG)"><img src="${CHART_IMAGE.src}" width="${CHART_IMAGE.width}" height="${CHART_IMAGE.height}" loading="lazy" decoding="async" alt="${CHART_IMAGE.alt}"></a>
<figcaption>Printable version of the same chart. <a href="${CHART_IMAGE.src}" download="cardology-birthday-chart.png">Download the PNG</a> or pin it above your desk like a warning. Generated from the same calculation as the table above.</figcaption>
</figure>`;
}
__name(renderBirthdayChart, "renderBirthdayChart");
function renderDayIndex() {
  const title = "Cardology Birthday Chart: All 366 Birthdays";
  const desc = "Free playing-cards birthday chart. Every date maps to one card in a 52-card deck. Browse all 366 birthdays, or let the calculator do it for you.";
  let body = `<div class="kicker">The Solar Calendar</div><h1>Every birthday. One card.</h1>
  <p>Cardology reads a standard deck as a symbolic solar calendar. 52 cards, 52 weeks, four suits, four seasons. Pick a birthday. See its card, ruling card, karma cards and life path. Then pretend you only looked up your own.</p>
  <p>Looking for a <strong>playing cards birthday chart</strong>? This directory is that chart. Pick any month and day to see the birthday playing card, ruling card and related layers. Prefer typing a date? Use the <a href="/birth-card-calculator">free birth card calculator</a>. Same fixed calendar, instant result, less scrolling.</p>
  <h2>How to use this chart</h2>
  <ul>
  <li>Find the month across the top and the day down the side. Each cell is that birthday\u2019s card, and opens its page.</li>
  <li>Or jump to the <a href="/birth-card-calculator">playing card birth card calculator</a> if you already know the date. You do.</li>
  <li>Then read the full meaning on the matching <a href="/birth-card">birth card</a> page. Yes, all of it.</li>
  </ul>
  <h2>The birthday chart: all 366 dates</h2>` + renderBirthdayChart();
  body += CTA_BLOCK;
  const crumbs = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: `${ORIGIN}/` },
      { "@type": "ListItem", position: 2, name: "Birthday Lookup", item: `${ORIGIN}/born-on/` }
    ]
  };
  const collection = {
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    name: title,
    description: desc,
    url: `${ORIGIN}/born-on/`,
    isPartOf: { "@type": "WebSite", name: "Card Blueprints", url: `${ORIGIN}/` },
    about: { "@type": "Thing", name: "Cardology birth cards by birthday" }
  };
  return shell({ title, desc, canonical: `${ORIGIN}/born-on/`, body, jsonld: [collection, crumbs] });
}
__name(renderDayIndex, "renderDayIndex");
function renderSitemap() {
  let urls = [`${ORIGIN}/born-on/`];
  for (let m = 1; m <= 12; m++)
    for (let d = 1; d <= DAYS_IN_MONTH[m - 1]; d++)
      urls.push(`${ORIGIN}/born-on/${daySlug(m, d)}`);
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map((u) => `<url><loc>${u}</loc><changefreq>monthly</changefreq></url>`).join("\n")}
</urlset>`;
}
__name(renderSitemap, "renderSitemap");

