// src/compatibility.js
var CC_SLUGS = JSON.stringify(Array.from({ length: 53 }, (_, v) => {
  if (v === 0) return null;
  const c = blueprint_default.SOLAR_TO_CARD[String(v)];
  return c ? cardSlug(c) : null;
}));
var CC_NAMES = JSON.stringify(Array.from({ length: 53 }, (_, v) => {
  if (v === 0) return "the Joker";
  const c = blueprint_default.SOLAR_TO_CARD[String(v)];
  return c ? cardName(c).replace("the ", "") : "";
}));
var CC_IDX = JSON.stringify(Object.fromEntries(ORDER.map((c, i3) => [cardSlug(c), i3])));
var CC_SCRIPT = `<script>
(function(){
if(window.__ccInit)return;window.__ccInit=1;
var S=${CC_SLUGS},N=${CC_NAMES},X=${CC_IDX};
var DIM=[31,29,31,30,31,30,31,31,30,31,30,31];
var SK='cardblueprints.analytics.session',AK='cardblueprints.analytics.attribution',OK='cardblueprints.analytics.once.';
function uid(){try{if(typeof crypto!=='undefined'&&crypto.randomUUID)return crypto.randomUUID()}catch(e){}
var h='';for(var i=0;i<36;i++){h+=(i===8||i===13||i===18||i===23)?'-':(i===14?'4':(i===19?'89ab'.charAt(Math.floor(Math.random()*4)):Math.floor(Math.random()*16).toString(16)))}return h}
function isSE(h){var L=['google.','bing.','duckduckgo.','yahoo.','ecosia.','brave.','yandex.','baidu.','startpage.','qwant.'];for(var i=0;i<L.length;i++){if(h.indexOf(L[i])===0||h.indexOf('.'+L[i])>0)return true}return false}
function attr(){
var f={sessionId:uid(),landingPath:location.pathname,referrerHost:'',trafficChannel:'unknown',utmSource:'',utmMedium:'',utmCampaign:''};
try{
var st=sessionStorage.getItem(AK);if(st)return JSON.parse(st);
var p=new URLSearchParams(location.search),rh='';
try{rh=document.referrer?new URL(document.referrer).hostname.toLowerCase().slice(0,120):''}catch(e){}
var us=(p.get('utm_source')||'').trim().slice(0,80),um=(p.get('utm_medium')||'').trim().slice(0,80),uc=(p.get('utm_campaign')||'').trim().slice(0,80);
var ch=(us||um)?(um.toLowerCase()==='organic'?'organic':'campaign'):(isSE(rh)?'organic':((!rh||rh===location.hostname)?'direct':'referral'));
var a={sessionId:sessionStorage.getItem(SK)||uid(),landingPath:location.pathname,referrerHost:rh,trafficChannel:ch,utmSource:us,utmMedium:um,utmCampaign:uc};
sessionStorage.setItem(SK,a.sessionId);sessionStorage.setItem(AK,JSON.stringify(a));return a
}catch(e){return f}}
function track(name,pl){
try{
var k=OK+name+':'+pl;
try{if(sessionStorage.getItem(k))return;sessionStorage.setItem(k,'1')}catch(e){}
var a=attr();
var b=JSON.stringify({eventName:name,eventId:uid(),sessionId:a.sessionId,path:location.pathname,landingPath:a.landingPath,referrerHost:a.referrerHost,trafficChannel:a.trafficChannel,utmSource:a.utmSource,utmMedium:a.utmMedium,utmCampaign:a.utmCampaign,offerSlug:'',placement:pl,outcome:''});
if(navigator.sendBeacon&&navigator.sendBeacon('/api/analytics',new Blob([b],{type:'application/json'})))return;
fetch('/api/analytics',{method:'POST',headers:{'content-type':'application/json'},body:b,keepalive:true,credentials:'same-origin'}).catch(function(){})
}catch(e){}}
function md(v){var p=(v||'').trim().split('-');var mo,d;
if(p.length===3){if(p[0].length!==4)return null;mo=+p[1];d=+p[2]}else if(p.length===2){mo=+p[0];d=+p[1]}else return null;
if(!isFinite(mo)||!isFinite(d))return null;mo=Math.floor(mo);d=Math.floor(d);
if(mo<1||mo>12||d<1||d>DIM[mo-1])return null;return[mo,d]}
function sval(mo,d){var v=55-(2*mo+d);return v<0?v+52:v}
function boot(f){
if(f.__cc)return;f.__cc=1;
var pl=f.getAttribute('data-cc'),A=f.querySelector('input[name=a]'),B=f.querySelector('input[name=b]'),out=f.querySelector('.cc-out');
if(!A||!B||!out)return;
function started(){track('calculator_started',pl)}
A.addEventListener('focus',started);B.addEventListener('focus',started);
function calc(nav){
var pa=md(A.value),pb=md(B.value);
if(!pa||!pb){out.innerHTML='';return false}
var sa=sval(pa[0],pa[1]),sb=sval(pb[0],pb[1]);
if(sa===0||sb===0){out.innerHTML='December 31 is the Joker. The Joker does not do pair pages. <a href="/born-on/december-31">See the Joker birthday page</a>.';return false}
var la=S[sa],lb=S[sb];
var path=(X[la]<=X[lb])?('/compatibility/'+la+'-and-'+lb):('/compatibility/'+lb+'-and-'+la);
out.innerHTML='You: <strong>'+N[sa]+'</strong> &middot; Them: <strong>'+N[sb]+'</strong>. <a href="'+path+'">Open the pair page</a>, if you can handle it.';
track('calculator_completed',pl);
if(nav)location.href=path;
return true}
A.addEventListener('change',function(){calc(false)});
B.addEventListener('change',function(){calc(false)});
f.addEventListener('submit',function(e){if(!md(A.value)||!md(B.value))return;e.preventDefault();calc(true)})}
function all(){var L=document.querySelectorAll('form[data-cc]');for(var i=0;i<L.length;i++)boot(L[i])}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',all)}else{all()}
})();
</script>`;
function renderCompatCalculator(opts) {
  const o = opts || {};
  const pl = o.placement || "compat-calculator";
  const form = `<form class="cc" method="post" action="/compatibility/" data-cc="${pl}">
<p class="cc-lede"><strong>Have both birthdays?</strong> Of course you do. Enter them and land on the exact pair page. No hunting through the 52-card grid.</p>
<div class="cc-row">
<label for="cc-a">Your birthday<input id="cc-a" type="date" name="a" required></label>
<label for="cc-b">Their birthday<input id="cc-b" type="date" name="b" required></label>
<button class="btn" type="submit">Compare our cards</button>
</div>
<p class="cc-out" role="status" aria-live="polite"></p>
<p class="muted cc-note">Calculated on this page. Your birthday is never stored.</p>
</form>${CC_SCRIPT}`;
  return o.collapsed ? `<details class="ccd"><summary>Compare two other birthdays. We won't ask whose.</summary>${form}</details>` : form;
}
__name(renderCompatCalculator, "renderCompatCalculator");
var SUIT_DYN = {
  "\u2665\u2665": ["Emotion meets Emotion", "Two Hearts. You love deeply and you merge fast. Six months in, neither of you knows whose opinion is whose. Keep separate friends. Keep separate playlists. Practice emotional differentiation."],
  "\u2665\u2663": ["Feeling meets Thinking", "One of you leads with the heart, the other with the head. One of you wants a hug, the other sends a bulleted list. Translate feelings into words. Listen to understand, not to fix."],
  "\u2665\u2666": ["Care meets Values", "Keep love and money in separate conversations. Set boundaries around time and resources early, before somebody starts keeping score in the notes app."],
  "\u2665\u2660": ["Sensitivity meets Intensity", "Repair fast after a fight. Pace the emotional weather. Neither of you is a project. Stop trying to renovate each other."],
  "\u2663\u2663": ["Mind meets Mind", "Endless conversation is your gift and your trap. You have discussed the trip for eleven months. Turn one shared idea into an actual booking."],
  "\u2663\u2666": ["Ideas meet Practicality", "Plan together. Decide how decisions get made, then anchor the vision in goals you can measure, so the dreamer and the builder stay on one team instead of two group chats."],
  "\u2663\u2660": ["Intellect meets Mastery", "Agree on the difference between debating and discussing. Respect each other's solitude. Respect each other's need to be challenged too, even when it is annoying."],
  "\u2666\u2666": ["Value meets Value", "Agree on standards and priorities. Be fully transparent about resources. Two Diamonds keeping separate ledgers will eventually audit each other, and nobody enjoys that meeting."],
  "\u2666\u2660": ["Resources meet Rigor", "Align on timelines and recovery habits. Your work ethics differ in style, not in seriousness. One of you rests. The other finds that suspicious. Respect the difference."],
  "\u2660\u2660": ["Mastery meets Mastery", "Leave room for each other to change. Support each other's work without arguing over whose mountain is steeper. It is not a competition. You are both making it one."]
};
function suitDyn(a, b) {
  return SUIT_DYN[suitOf(a) + suitOf(b)] || SUIT_DYN[suitOf(b) + suitOf(a)];
}
__name(suitDyn, "suitDyn");
